{
  "interpretation": {
    "name": "TightenBracketFastenersLine1",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Tighten the fasteners of the mounting bracket at station st1 on line 1 with the shared nutrunner NR7, then evaluate and record the result. The welding part of the request is not covered by this Recipe.",
    "constraints": [
      "NR7 must be reserved before use and released afterwards",
      "NR7 must be at st1 (transport-tool to 'station' completed) before configure-tool and tighten-fasteners",
      "transport-tool must be delegated to agvexecutor",
      "The tightening program comes only from get-program for variant F25, with no literal values in the Recipe",
      "The tightening must be evaluated and recorded",
      "Every tool-using Step renews the lease with the reservation token, so it depends on reserve-tool"
    ],
    "preference": "Return the shared tool to the crib after use so that other lines can use it.",
    "priority": "normal",
    "horizon": "current request, single execution",
    "requested_capabilities": ["weld mounting bracket"],
    "omit_services": []
  },
  "recipe": {
    "name": "tighten-bracket-fasteners-line1",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "verify",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten-bolts"],
            "dep": ["program", "reserve"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-bolts",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure", "reserve"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "verify",
        "next": "return-and-release",
        "steps": [
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-bolts", "program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-bolts"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-and-release",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release"],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
